import {fresh,view,choose,chooseBatch,VERSION,supportedVersion,enterSequel} from './engine.js';
const readSave=(db,user)=>db.prepare('SELECT revision,payload FROM saves WHERE user_id = ?').bind(user).first();
export async function load(db,user){let row=await readSave(db,user);if(!row){const s=fresh();await db.prepare('INSERT OR IGNORE INTO saves (user_id,revision,payload,updated_at) VALUES (?,?,?,?)').bind(user,0,JSON.stringify(s),new Date().toISOString()).run();row=await readSave(db,user);}let state=JSON.parse(row.payload);if(!supportedVersion(state.version)){const next=fresh();next.revision=row.revision+1;const now=new Date().toISOString();await db.batch([db.prepare('INSERT OR IGNORE INTO archives (id,user_id,payload,created_at) VALUES (?,?,?,?)').bind(user+':'+state.version+':'+row.revision,user,row.payload,now),db.prepare('UPDATE saves SET revision=?,payload=?,updated_at=? WHERE user_id=? AND revision=?').bind(next.revision,JSON.stringify(next),now,user,row.revision)]);row=await readSave(db,user);state=JSON.parse(row.payload);}return state;}
export async function act(db,user,{revision,choice,confirm,route},kind='choose',batch=false){const current=await load(db,user);if(!Number.isInteger(revision)||revision!==current.revision){const e=Error('进度已更新，请先读取当前状态再选择');e.status=409;e.state=current;throw e;}let next;if(kind==='sequel'){if(confirm!==true)throw Error('需要确认归档当前进度并进入续篇');let base=current;if(route==='continue'){const nowView=view(current);if(current.episode===2||!nowView.ended||![1,2,3].includes(nowView.stats.ending)){const rows=await db.prepare('SELECT payload,created_at FROM archives WHERE user_id=? ORDER BY created_at DESC LIMIT 10').bind(user).all();base=null;for(const row of rows.results){try{const candidate=JSON.parse(row.payload);if(candidate.episode===2||!supportedVersion(candidate.version))continue;const cv=view(candidate);if(cv.ended&&[1,2,3].includes(cv.stats.ending)){base=candidate;break;}}catch{}}if(!base)throw Error('没有找到已完成的第一部记录。可以先完成第一部，或选择一条独立试玩路线。');}}next=enterSequel(base,route);next.revision=current.revision+1;await db.prepare('INSERT INTO archives (id,user_id,payload,created_at) VALUES (?,?,?,?)').bind(crypto.randomUUID(),user,JSON.stringify(current),new Date().toISOString()).run();}else if(kind==='restart'){if(confirm!==true)throw Error('需要明确确认重新开始');next=fresh();next.revision=current.revision+1;await db.prepare('INSERT INTO archives (id,user_id,payload,created_at) VALUES (?,?,?,?)').bind(crypto.randomUUID(),user,JSON.stringify(current),new Date().toISOString()).run();}else{if(typeof choice!=='string')throw Error('缺少有效选项');next=batch?chooseBatch(current,choice):choose(current,choice);}const result=await db.prepare('UPDATE saves SET revision=?,payload=?,updated_at=? WHERE user_id=? AND revision=?').bind(next.revision,JSON.stringify(next),new Date().toISOString(),user,current.revision).run();if(!result.meta.changes){const e=Error('进度已更新，请先读取当前状态再选择');e.status=409;e.state=await load(db,user);throw e;}return next;}
